--
-- Table structure for table `sys_tag_rel`
--

DROP TABLE IF EXISTS `sys_tag_rel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_tag_rel` (
  `rel_id` bigint NOT NULL AUTO_INCREMENT COMMENT '关联ID',
  `tag_id` bigint NOT NULL COMMENT '标签ID',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型，如 purchase_supplier',
  `biz_id` bigint NOT NULL COMMENT '业务主键',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`rel_id`),
  UNIQUE KEY `uk_tag_rel` (`biz_type`,`biz_id`,`tag_id`),
  KEY `idx_rel_biz` (`biz_type`,`biz_id`),
  KEY `idx_rel_tag` (`tag_id`,`biz_type`)
) ENGINE=InnoDB AUTO_INCREMENT=1830 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统标签关联（通用多对多）';
/*!40101 SET character_set_client = @saved_cs_client */;

