--
-- Table structure for table `hr_employee`
--

DROP TABLE IF EXISTS `hr_employee`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hr_employee` (
  `emp_id` bigint NOT NULL AUTO_INCREMENT COMMENT '员工ID',
  `emp_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工号',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `sex` tinyint DEFAULT NULL COMMENT '性别 1男 2女',
  `dept_id` bigint DEFAULT NULL COMMENT '部门ID(sys_dept.dept_id)',
  `position` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '岗位（字典 hr_position）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `hire_date` date DEFAULT NULL COMMENT '进厂日期',
  `leave_date` date DEFAULT NULL COMMENT '离职日期',
  `employment_status` tinyint NOT NULL DEFAULT '2' COMMENT '在职状态 1试用 2正式 3停薪留职 9离职',
  `id_card_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号（AES 加密存储）',
  `id_card_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证地址（敏感）',
  `current_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '现住址（敏感）',
  `education` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历（字典 hr_education）',
  `major` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业',
  `resume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '个人履历',
  `user_id` bigint DEFAULT NULL COMMENT '关联系统账号 sys_user.user_id（可空，一对一）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '删除标记 0正常 2删除',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`emp_id`),
  UNIQUE KEY `uk_hr_emp_no` (`emp_no`),
  UNIQUE KEY `uk_hr_emp_phone` (`phone`),
  UNIQUE KEY `uk_hr_emp_user` (`user_id`),
  UNIQUE KEY `uk_hr_emp_idcard` (`id_card_no`),
  KEY `idx_hr_emp_dept` (`dept_id`),
  KEY `idx_hr_emp_status` (`employment_status`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='员工档案（人事主数据；账号可选关联；岗位走字典 hr_position）';
